import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validate successful registration for a new Todo List user account.
 *
 * This test covers business rules for unique business email, password
 * requirements, and required session/audit context fields. Steps:
 *
 * 1. Generate unique business email and strong password.
 * 2. Register new user with all required audit context fields (href/referrer).
 * 3. Assert a successful response and NO password leakage.
 * 4. Confirm the verification email process and 'pending verification' status.
 * 5. Validate audit fields (created_at, updated_at), and basic user profile info
 *    in the returned data.
 *
 * Password must never be leaked. Email must be unique per test, strongly typed.
 * Audit and session context fields are validated.
 */
export async function test_api_todo_list_user_registration_success(
  connection: api.IConnection,
) {
  // 1. Generate strong random business email and password
  const businessDomain = "@company.com";
  const userEmail =
    `${RandomGenerator.alphabets(8)}.${RandomGenerator.alphabets(4)}${businessDomain}` satisfies string &
      tags.Format<"email">;
  const userPassword = RandomGenerator.alphaNumeric(14) + "aA!1"; // ensure strong (add complexity)
  const userHref =
    "https://business-app.company.com/register" satisfies string &
      tags.Format<"uri">;
  const userReferrer = "https://start.company.com/cta" satisfies string &
    tags.Format<"uri">;
  const displayName = RandomGenerator.name();

  // 2. Register user
  const registration = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword satisfies string & tags.Format<"password">,
      href: userHref,
      referrer: userReferrer,
      display_name: displayName,
    } satisfies ITodoListUser.ICreate,
  });
  typia.assert(registration);

  // 3. Check password is not in the response
  TestValidator.predicate(
    "response does not leak password",
    typeof (registration as any)["password"] === "undefined" &&
      Object.values(registration).every(
        (v) => typeof v !== "string" || !v.includes(userPassword),
      ) &&
      (typeof registration.user !== "object" ||
        registration.user == null ||
        Object.values(registration.user).every(
          (v) => typeof v !== "string" || !v.includes(userPassword),
        )),
  );

  // 4. Audit core result fields
  TestValidator.equals(
    "registered email matches request",
    registration.email,
    userEmail,
  );
  TestValidator.equals(
    "display_name matches",
    registration.display_name,
    displayName,
  );

  // 5. Check user profile object
  if (registration.user !== undefined && registration.user !== null) {
    TestValidator.equals(
      "profile id matches main id",
      registration.user.id,
      registration.id,
    );
    TestValidator.equals(
      "profile email matches",
      registration.user.email,
      registration.email,
    );
    TestValidator.equals(
      "profile display_name matches",
      registration.user.display_name,
      registration.display_name,
    );
    TestValidator.equals(
      "profile created_at matches",
      registration.user.created_at,
      registration.created_at,
    );
    TestValidator.equals(
      "profile updated_at matches",
      registration.user.updated_at,
      registration.updated_at,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Test failed registration for a user when the provided email address already
 * exists in the system.
 *
 * Attempt two subsequent registrations with the same email. The first
 * registration should succeed, triggering standard flows. The second attempt,
 * using the same email, must fail with a relevant error message indicating
 * email uniqueness violation and must NOT create a new user record or trigger a
 * new verification email.
 *
 * This validates strict unique constraint enforcement and duplicate account
 * prevention.
 */
export async function test_api_todo_list_user_registration_duplicate_email(
  connection: api.IConnection,
) {
  // Prepare unique email for registration
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const href = "https://app.example.com/signup";
  const referrer = "https://app.example.com/landing";
  const display_name = RandomGenerator.name();

  // First registration: should succeed
  const result = await api.functional.auth.user.join(connection, {
    body: {
      email,
      password: password satisfies string as string,
      href,
      referrer,
      display_name,
    } satisfies ITodoListUser.ICreate,
  });
  typia.assert(result);
  TestValidator.equals("registered email matches", result.email, email);
  TestValidator.equals(
    "display name matches",
    result.display_name,
    display_name,
  );
  TestValidator.predicate(
    "token has access string",
    typeof result.token.access === "string" && result.token.access.length > 0,
  );
  TestValidator.predicate(
    "created_at is ISO",
    typeof result.created_at === "string" &&
      !isNaN(Date.parse(result.created_at)),
  );

  // Second registration with same email: should fail
  await TestValidator.error(
    "duplicate email registration should fail",
    async () => {
      await api.functional.auth.user.join(connection, {
        body: {
          email,
          password: password satisfies string as string,
          href,
          referrer,
          display_name,
        } satisfies ITodoListUser.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Test that login is forbidden using email and password for a just-registered
 * user whose email is still unverified.
 *
 * 1. Register a new user, but do NOT perform any email verification simulation or
 *    completion process.
 * 2. Attempt to log in with the just-registered user's correct email and password.
 * 3. The login should fail: TestValidator.error must be used to verify that the
 *    login is rejected due to unverified email.
 * 4. The failure code path must NOT issue any IAuthorizationToken or session.
 *
 * This test enforces the business rule: login is only allowed after email
 * verification is successfully completed.
 */
export async function test_api_todo_list_user_login_fail_unverified_email(
  connection: api.IConnection,
) {
  // 1. Register user but do not verify the email
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const joinInput = {
    email,
    password,
    href: "https://test-app.example/join",
    referrer: "https://test-app.example/landing",
    display_name: RandomGenerator.name(),
  } satisfies ITodoListUser.ICreate;
  const registered = await api.functional.auth.user.join(connection, {
    body: joinInput,
  });
  typia.assert(registered);

  // 2. Try to login with the new account, which is unverified
  await TestValidator.error("login must fail for unverified user", async () => {
    await api.functional.auth.user.login(connection, {
      body: {
        email,
        password,
        href: "https://test-app.example/login",
        referrer: "https://test-app.example/login",
      } satisfies ITodoListUser.ILogin,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validate that user login fails with incorrect password.
 *
 * This test ensures that the API correctly rejects login attempts with a wrong
 * password. The workflow involves:
 *
 * 1. Registering a new user (using /auth/user/join, simulating verified user).
 * 2. Attempting to login with the correct email but an incorrect password.
 * 3. Asserting that authentication fails (TestValidator.error) and no
 *    token/session is issued.
 *
 * Steps:
 *
 * - Generate a random email and password for registration.
 * - Register the user and verify successful registration.
 * - Attempt to login with same email and an intentionally wrong password.
 * - Assert that the API returns a business error and does not issue an
 *   authentication token.
 */
export async function test_api_todo_list_user_login_fail_wrong_password(
  connection: api.IConnection,
) {
  // 1. Register a new user (simulate verified)
  const email = typia.random<string & tags.Format<"email">>();
  const correctPassword = typia.random<string & tags.Format<"password">>();
  const joinBody = {
    email,
    password: correctPassword,
    href: "https://app.autobe.com/register",
    referrer: "https://app.autobe.com/",
    display_name: RandomGenerator.name(),
  } satisfies ITodoListUser.ICreate;
  const joinOutput = await api.functional.auth.user.join(connection, {
    body: joinBody,
  });
  typia.assert(joinOutput);
  // (Simulate verified user. If needed for real SUT, insert verification step here.)

  // 2. Attempt login with correct email, wrong password
  const wrongPassword = correctPassword + "1";
  const loginBody = {
    email,
    password: wrongPassword,
    href: "https://app.autobe.com/login",
    referrer: "https://app.autobe.com/",
  } satisfies ITodoListUser.ILogin;
  await TestValidator.error(
    "login should fail with incorrect password",
    async () => {
      await api.functional.auth.user.login(connection, { body: loginBody });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoListUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListUserSession";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import type { ITodoListUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserSession";

/**
 * Test paginated search and audit filtering for a user's authentication
 * sessions.
 *
 * Covers all metadata filters and pagination/sorting.
 *
 * 1. Generate a userId (UUID)
 * 2. Create a diverse set of session data for this user (ip, href, referrer,
 *    created_at, expired_at)
 * 3. Create out-of-user (other user) sessions for negative test
 * 4. Test unfiltered search returns all user-owned sessions only
 * 5. Test filter by ip (partial and exact)
 * 6. Test filter by href (origin) and referrer (substring)
 * 7. Test filter by date range (created_from/created_to)
 * 8. Test filter by expired=true
 * 9. Test filter by expired=false (active sessions only)
 * 10. Test combined filters
 * 11. Test pagination (page/limit) and sort options
 * 12. Test search for another user's sessions (should not be exposed)
 * 13. For every search, validate paged, sorted, filtered session results are
 *     correct and all access control rules are enforced.
 */
export async function test_api_user_sessions_audit_search(
  connection: api.IConnection,
) {
  // Data setup
  const userId = typia.random<string & tags.Format<"uuid">>();
  const otherUserId = typia.random<string & tags.Format<"uuid">>();
  const sessionCount = 10;
  // Diverse IPs, hrefs, referrers, timestamps
  const ips = ["10.0.1.1", "192.168.2.100", "127.0.0.1", "172.22.2.2"];
  const hrefs = [
    "https://login.todo.com",
    "https://app.todo.com/start",
    "https://m.todo.com/",
  ];
  const referrers = [
    "https://google.com",
    "https://company.com",
    "https://todo.com/register",
  ];
  const now = new Date();
  // Sessions for main user
  const sessions: ITodoListUserSession.ISummary[] = ArrayUtil.repeat(
    sessionCount,
    (i) => {
      const created_at = new Date(
        now.getTime() - i * 60 * 60 * 1000,
      ).toISOString(); // oldest later idx
      const expired_at =
        i % 3 === 0
          ? new Date(now.getTime() - i * 30 * 60 * 1000).toISOString()
          : null;
      return {
        id: typia.random<string & tags.Format<"uuid">>(),
        ip: RandomGenerator.pick(ips),
        href: RandomGenerator.pick(hrefs) as string & tags.Format<"uri">,
        referrer: RandomGenerator.pick(referrers) as string &
          tags.Format<"uri">,
        created_at,
        expired_at,
        user: {
          id: userId,
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(2),
          created_at: new Date(now.getTime() - 10000).toISOString(),
        },
      };
    },
  );
  // Sessions for another user (should never be shown in userId-scoped queries)
  const otherSessions: ITodoListUserSession.ISummary[] = ArrayUtil.repeat(
    3,
    (i) => ({
      id: typia.random<string & tags.Format<"uuid">>(),
      ip: "203.0.113.10",
      href: "https://rogue.todo.com/",
      referrer: "https://evil.com/",
      created_at: new Date(now.getTime() - (i + 6) * 3600000).toISOString(),
      expired_at: null,
      user: {
        id: otherUserId,
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(1),
        created_at: new Date(now.getTime() - 30000).toISOString(),
      },
    }),
  );
  // Combine for local manual filtering
  const allSessions = [...sessions, ...otherSessions];
  // 1. Unfiltered search (should return ALL sessions for userId, paginated)
  {
    const body = {
      page: 1 as number & tags.Type<"int32">,
      limit: 100 as number & tags.Type<"int32">,
    } satisfies ITodoListUserSession.IRequest;
    const res = await api.functional.todoList.users.sessions.index(connection, {
      userId,
      body,
    });
    typia.assert(res);
    const gotSessionIds = res.data.map((s) => s.id);
    TestValidator.equals(
      "return all sessions matching userId",
      gotSessionIds.sort(),
      sessions.map((s) => s.id).sort(),
    );
    // Confirm all returned sessions are for correct user
    TestValidator.predicate(
      "every result session.user.id = userId",
      res.data.every((sess) => sess.user.id === userId),
    );
  }
  // 2. Filter by IP (partial, should match some sessions)
  {
    const targetIpFragment = sessions[1].ip.substring(0, 5);
    const expectedSessions = sessions.filter((x) =>
      x.ip.includes(targetIpFragment),
    );
    const body = {
      ip: targetIpFragment,
      page: 1 as number & tags.Type<"int32">,
      limit: 50 as number & tags.Type<"int32">,
    } satisfies ITodoListUserSession.IRequest;
    const res = await api.functional.todoList.users.sessions.index(connection, {
      userId,
      body,
    });
    typia.assert(res);
    const gotIds = res.data.map((s) => s.id);
    TestValidator.equals(
      "filter by partial IP matches expected",
      gotIds.sort(),
      expectedSessions.map((x) => x.id).sort(),
    );
  }
  // 3. Filter by href (origin, exact)
  {
    const targetHref = sessions[2].href;
    const body = {
      href: targetHref,
      page: 1 as number & tags.Type<"int32">,
      limit: sessionCount as number & tags.Type<"int32">,
    } satisfies ITodoListUserSession.IRequest;
    const expectedSessions = sessions.filter((x) => x.href === targetHref);
    const res = await api.functional.todoList.users.sessions.index(connection, {
      userId,
      body,
    });
    typia.assert(res);
    TestValidator.equals(
      "exact href search results",
      res.data.length,
      expectedSessions.length,
    );
    TestValidator.equals(
      "matching session ids for href",
      res.data.map((x) => x.id).sort(),
      expectedSessions.map((x) => x.id).sort(),
    );
  }
  // 4. Filter by referrer (substring)
  {
    const substring = sessions[1].referrer.slice(0, 15);
    const expectedSessions = sessions.filter((x) =>
      x.referrer.includes(substring),
    );
    const body = {
      referrer: substring,
      page: 1 as number & tags.Type<"int32">,
      limit: 30 as number & tags.Type<"int32">,
    } satisfies ITodoListUserSession.IRequest;
    const res = await api.functional.todoList.users.sessions.index(connection, {
      userId,
      body,
    });
    typia.assert(res);
    TestValidator.equals(
      "substring referrer filter works",
      res.data.length,
      expectedSessions.length,
    );
  }
  // 5. Filter by date range (created_from, created_to)
  {
    // Take some sessions to get date bounds
    const boundA = sessions[2].created_at;
    const boundB = sessions[7].created_at;
    // pick min/max
    const created_from = boundB < boundA ? boundB : boundA;
    const created_to = boundB < boundA ? boundA : boundB;
    const expectedSessions = sessions.filter(
      (s) => s.created_at >= created_from && s.created_at <= created_to,
    );
    const body = {
      created_from,
      created_to,
      page: 1 as number & tags.Type<"int32">,
      limit: 50 as number & tags.Type<"int32">,
    } satisfies ITodoListUserSession.IRequest;
    const res = await api.functional.todoList.users.sessions.index(connection, {
      userId,
      body,
    });
    typia.assert(res);
    TestValidator.equals(
      "date range search returns correct count",
      res.data.length,
      expectedSessions.length,
    );
  }
  // 6. Filter by expired=true/false
  {
    // true -> only with expired_at present
    const bodyExpired = {
      expired: true,
      page: 1 as number & tags.Type<"int32">,
      limit: 50 as number & tags.Type<"int32">,
    } satisfies ITodoListUserSession.IRequest;
    const expected = sessions.filter(
      (x) => x.expired_at !== null && x.expired_at !== undefined,
    );
    const res = await api.functional.todoList.users.sessions.index(connection, {
      userId,
      body: bodyExpired,
    });
    typia.assert(res);
    TestValidator.equals(
      "expired:true returns sessions that are expired",
      res.data.map((x) => x.id).sort(),
      expected.map((x) => x.id).sort(),
    );
    // false (undefined) -> all sessions
    const bodyActive = {
      expired: false,
      page: 1 as number & tags.Type<"int32">,
      limit: 50 as number & tags.Type<"int32">,
    } satisfies ITodoListUserSession.IRequest;
    const expectedActive = sessions.filter(
      (x) => x.expired_at === null || x.expired_at === undefined,
    );
    const resActive = await api.functional.todoList.users.sessions.index(
      connection,
      { userId, body: bodyActive },
    );
    typia.assert(resActive);
    TestValidator.equals(
      "expired:false returns only non-expired",
      resActive.data.map((x) => x.id).sort(),
      expectedActive.map((x) => x.id).sort(),
    );
  }
  // 7. Combined filters: IP + href + referrer + expired
  {
    const targetSess = sessions[0];
    const body = {
      ip: targetSess.ip,
      href: targetSess.href,
      referrer: targetSess.referrer,
      expired:
        targetSess.expired_at !== null && targetSess.expired_at !== undefined,
      page: 1 as number & tags.Type<"int32">,
      limit: 10 as number & tags.Type<"int32">,
    } satisfies ITodoListUserSession.IRequest;
    const expected = sessions.filter(
      (x) =>
        x.ip === targetSess.ip &&
        x.href === targetSess.href &&
        x.referrer === targetSess.referrer &&
        ((body.expired &&
          x.expired_at !== null &&
          x.expired_at !== undefined) ||
          (!body.expired &&
            (x.expired_at === null || x.expired_at === undefined))),
    );
    const res = await api.functional.todoList.users.sessions.index(connection, {
      userId,
      body,
    });
    typia.assert(res);
    TestValidator.equals(
      "combined filters returns correct set",
      res.data.map((x) => x.id).sort(),
      expected.map((x) => x.id).sort(),
    );
  }
  // 8. Pagination testing (small limit, get 1st and 2nd pages, sort desc)
  {
    const body = {
      page: 1 as number & tags.Type<"int32">,
      limit: 4 as number & tags.Type<"int32">,
      sort: "created_at:desc",
    } satisfies ITodoListUserSession.IRequest;
    const sortedSessions = [...sessions].sort((a, b) =>
      b.created_at.localeCompare(a.created_at),
    );
    const page1 = await api.functional.todoList.users.sessions.index(
      connection,
      { userId, body },
    );
    typia.assert(page1);
    TestValidator.equals(
      "pagination: page 1 count matches limit",
      page1.data.length,
      body.limit,
    );
    TestValidator.equals(
      "pagination: page 1 IDs match sorted",
      page1.data.map((x) => x.id),
      sortedSessions.slice(0, body.limit).map((x) => x.id),
    );
    // Next page
    const body2 = {
      ...body,
      page: 2 as number & tags.Type<"int32">,
    } satisfies ITodoListUserSession.IRequest;
    const page2 = await api.functional.todoList.users.sessions.index(
      connection,
      { userId, body: body2 },
    );
    typia.assert(page2);
    TestValidator.equals(
      "pagination: page 2 count matches remainder or zero",
      page2.data.length,
      Math.max(0, sortedSessions.length - body.limit),
    );
    TestValidator.equals(
      "pagination: page 2 IDs match sorted",
      page2.data.map((x) => x.id),
      sortedSessions.slice(body.limit, body.limit * 2).map((x) => x.id),
    );
  }
  // 9. Sorting by created_at:asc and expired_at:desc (if applicable)
  {
    // created_at ascending
    const bodyAsc = {
      page: 1 as number & tags.Type<"int32">,
      limit: sessionCount as number & tags.Type<"int32">,
      sort: "created_at:asc",
    } satisfies ITodoListUserSession.IRequest;
    const ascSorted = [...sessions].sort((a, b) =>
      a.created_at.localeCompare(b.created_at),
    );
    const pageAsc = await api.functional.todoList.users.sessions.index(
      connection,
      { userId, body: bodyAsc },
    );
    typia.assert(pageAsc);
    TestValidator.equals(
      "sort created_at:asc",
      pageAsc.data.map((x) => x.id),
      ascSorted.map((x) => x.id),
    );
    // expired_at desc, filter to expired only
    const expired = sessions.filter(
      (x) => x.expired_at !== null && x.expired_at !== undefined,
    );
    if (expired.length > 1) {
      const bodyExp = {
        page: 1 as number & tags.Type<"int32">,
        limit: expired.length as number & tags.Type<"int32">,
        sort: "expired_at:desc",
        expired: true,
      } satisfies ITodoListUserSession.IRequest;
      const sortedExp = [...expired].sort((a, b) =>
        b.expired_at!.localeCompare(a.expired_at!),
      );
      const pageSortExp = await api.functional.todoList.users.sessions.index(
        connection,
        { userId, body: bodyExp },
      );
      typia.assert(pageSortExp);
      TestValidator.equals(
        "sort expired_at:desc",
        pageSortExp.data.map((x) => x.id),
        sortedExp.map((x) => x.id),
      );
    }
  }
  // 10. Access control: querying another user's sessions yields no data
  {
    const body = {
      page: 1 as number & tags.Type<"int32">,
      limit: 10 as number & tags.Type<"int32">,
    } satisfies ITodoListUserSession.IRequest;
    const res = await api.functional.todoList.users.sessions.index(connection, {
      userId: otherUserId,
      body,
    });
    typia.assert(res);
    TestValidator.equals(
      "other user's session search returns only their sessions",
      res.data.map((x) => x.user.id).every((id) => id === otherUserId),
      true,
    );
    // Should not leak sessions for the main userId
    TestValidator.predicate(
      "should not return test user sessions in otherUser results",
      res.data.every((sess) => sess.user.id !== userId),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ITodoListUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserSession";

export async function test_api_user_session_detail_retrieval(
  connection: api.IConnection,
) {
  /**
   * Test plan:
   *
   * 1. Generate random session and user IDs (UUID format) for input.
   * 2. (Mockup only) Try retrieving a session detail with given userId and
   *    sessionId using the endpoint.
   * 3. Validate the response structure and formats for all fields.
   * 4. Simulate success case: if session returned, check linkage (matching userId)
   *    and formats of id, timestamps, etc.
   * 5. Simulate expired session: manually set expired_at and check for correct
   *    value in response.
   * 6. Negative test: generate non-existent sessionId and expect API error on
   *    retrieval.
   * 7. Negative test: retrieve a session with mismatched userId (non-owner),
   *    expect error.
   */

  // 1. Create random user ID and session ID (UUID format)
  const userId = typia.random<string & tags.Format<"uuid">>();
  const sessionId = typia.random<string & tags.Format<"uuid">>();

  // 2. Retrieve the session detail (success for existing session)
  const session: ITodoListUserSession =
    await api.functional.todoList.users.sessions.at(connection, {
      userId,
      sessionId,
    });
  typia.assert(session);

  // 3. Validate linkage and field formats
  TestValidator.equals(
    "userId linkage matches",
    session.todo_list_user_id,
    userId,
  );
  TestValidator.predicate(
    "session.id is uuid",
    typeof session.id === "string" && session.id.length === 36,
  );
  TestValidator.predicate("ip is string", typeof session.ip === "string");
  TestValidator.predicate("href is string", typeof session.href === "string");
  TestValidator.predicate(
    "referrer is string",
    typeof session.referrer === "string",
  );
  TestValidator.predicate(
    "created_at is ISO date string",
    typeof session.created_at === "string" && /T.*Z$/.test(session.created_at),
  );
  // expired_at can be null/undefined (active) or ISO string (expired)
  if (session.expired_at !== null && session.expired_at !== undefined) {
    TestValidator.predicate(
      "expired_at is ISO date string if present",
      typeof session.expired_at === "string" &&
        /T.*Z$/.test(session.expired_at),
    );
  }

  // 4. Negative: retrieve with non-existent sessionId
  await TestValidator.error(
    "retrieving a non-existent session throws",
    async () => {
      await api.functional.todoList.users.sessions.at(connection, {
        userId,
        sessionId: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 5. Negative: attempt access using wrong userId
  await TestValidator.error(
    "cannot retrieve another user's session",
    async () => {
      await api.functional.todoList.users.sessions.at(connection, {
        userId: typia.random<string & tags.Format<"uuid">>(),
        sessionId,
      });
    },
  );
}

