import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Test the password reset request endpoint for a registered user email.
 *
 * 1. Generate a random, valid email address.
 * 2. (Assume user exists in DB for test purposes; if not, result is safe to show
 *    privacy masking)
 * 3. Send POST request to /auth/user/password/request-reset with the email in
 *    body.
 * 4. Confirm that response is of shape { success: boolean, message: string } and
 *    matches ITodoListUser.IPasswordResetStatus schema.
 * 5. Assert that success is true for known-good (registered) email, and the
 *    message is a nonempty string explaining next steps to user.
 * 6. Never expose whether account exists in system in response payload (privacy
 *    compliance, but in e2e for registered, success is expected).
 */
export async function test_api_password_reset_request_with_registered_email(
  connection: api.IConnection,
) {
  // 1. Generate a valid, random email for password reset (simulate registered user)
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const requestBody = { email } satisfies ITodoListUser.IRequestPasswordReset;

  // 2. Send the password reset request
  const response: ITodoListUser.IPasswordResetStatus =
    await api.functional.auth.user.password.request_reset.requestPasswordReset(
      connection,
      { body: requestBody },
    );
  typia.assert(response);

  // 3. Validate response fields
  TestValidator.predicate(
    "reset status should be success for registered email",
    response.success === true,
  );
  TestValidator.predicate(
    "status message should be a nonempty string",
    typeof response.message === "string" && response.message.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Test password reset request with an unregistered email address.
 *
 * This test ensures that the password reset endpoint never reveals whether an
 * email is registered. It verifies that any request using a non-existent email
 * yields a generic success response and no information about the existence of
 * the user is leaked. It also validates strict email format checks.
 *
 * Steps:
 *
 * 1. Generate a random, valid email that is guaranteed to NOT be in the user
 *    database.
 * 2. Request a password reset with this email using the proper API endpoint.
 * 3. Assert that the response is a generic success response (success true or false
 *    is acceptable, but error messages should not reference account
 *    existence).
 * 4. Validate the output structure/type using typia.assert.
 * 5. Check that status message does not violate privacy rules.
 * 6. Try an obviously invalid email format and ensure the API rejects it with an
 *    error.
 */
export async function test_api_password_reset_request_with_unregistered_email(
  connection: api.IConnection,
) {
  // 1. Generate a random, valid email address
  const unregisteredEmail =
    `unreg+${RandomGenerator.alphaNumeric(10)}@domain.test` as string &
      tags.Format<"email">;
  const requestBody = {
    email: unregisteredEmail,
  } satisfies ITodoListUser.IRequestPasswordReset;

  // 2. Call password reset endpoint with unregistered email
  const output =
    await api.functional.auth.user.password.request_reset.requestPasswordReset(
      connection,
      { body: requestBody },
    );

  // 3. Assert output has correct type/structure
  typia.assert<ITodoListUser.IPasswordResetStatus>(output);

  // 4. The response should not leak whether account exists
  // (Generic message, not e.g. "no user found" or similar)
  TestValidator.predicate(
    "status message reveals no account existence",
    typeof output.message === "string" &&
      !/not\s*found|not\s*exist|unknown user|no user/i.test(output.message),
  );

  // 5. The success property must be boolean
  TestValidator.predicate(
    "output.success is boolean",
    typeof output.success === "boolean",
  );

  // 6. Try invalid email format (should error)
  await TestValidator.error(
    "invalid email format should be rejected",
    async () => {
      await api.functional.auth.user.password.request_reset.requestPasswordReset(
        connection,
        { body: { email: "not-an-email" as string & tags.Format<"email"> } },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validates that a user can delete an active session (log out from another
 * device), enforcing session privacy/boundaries and proper forced logout audit
 * behavior.
 *
 * 1. Register a new user via join
 * 2. Log in twice to create two independent sessions (simulating two devices)
 * 3. Use the session deletion endpoint to delete one session by its sessionId
 *    (while authenticated as the same user)
 * 4. (If possible) Attempt to use the deleted session's token for an authenticated
 *    operation—it should fail (not possible in this strict SDK test context,
 *    but in real-world E2E you'd attempt an operation and expect an error)
 * 5. (Optional: business rule) Attempt to delete a session for a different user –
 *    should be denied
 *
 * Note: The SDK does not expose session UUIDs after login, so this test must
 * simulate session UUIDs. In a real backend, session deletion would use a real
 * sessionId, but here we use stub UUIDs.
 */
export async function test_api_session_deletion_by_user(
  connection: api.IConnection,
) {
  // 1. Register a new user
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const password: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();
  const createUserBody = {
    email,
    password,
    href: "https://app.todo-list.com/auth/register",
    referrer: "https://app.todo-list.com/landing",
    display_name: RandomGenerator.name(),
  } satisfies ITodoListUser.ICreate;
  const registered: ITodoListUser.IAuthorized =
    await api.functional.auth.user.join(connection, { body: createUserBody });
  typia.assert(registered);

  // 2. Log in twice to create two independent sessions
  const loginBody = {
    email,
    password,
    href: "https://app.todo-list.com/login",
    referrer: "https://app.todo-list.com/welcome",
  } satisfies ITodoListUser.ILogin;
  const session1 = await api.functional.auth.user.login(connection, {
    body: loginBody,
  });
  typia.assert(session1);
  const session2 = await api.functional.auth.user.login(connection, {
    body: loginBody,
  });
  typia.assert(session2);

  TestValidator.notEquals(
    "session tokens for two logins must be different",
    session1.token.access,
    session2.token.access,
  );

  // 3. Delete the first session (simulate with a stub sessionId)
  // SDK does not provide a real sessionId, so use a random UUID for test stub
  await api.functional.todoList.user.users.sessions.erase(connection, {
    userId: session2.id,
    sessionId: typia.random<string & tags.Format<"uuid">>(),
  });

  // 4. Not possible: Cannot simulate deleted session's token—no sessionId-linkage from SDK

  // 5. Attempt to delete another user's session (should fail)
  const otherUserBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    href: "https://app.todo-list.com/auth/register",
    referrer: "https://app.todo-list.com/landing",
  } satisfies ITodoListUser.ICreate;
  const otherUser = await api.functional.auth.user.join(connection, {
    body: otherUserBody,
  });
  typia.assert(otherUser);
  await TestValidator.error(
    "user cannot erase session of another user",
    async () => {
      await api.functional.todoList.user.users.sessions.erase(connection, {
        userId: otherUser.id,
        sessionId: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListTodo";
import type { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validate robust search, filtering, and pagination of user's Todo list.
 *
 * This test covers:
 *
 * 1. User registration and login
 * 2. Creation of numerous Todos for variety
 * 3. Searching the user's own todos by:
 *
 *    - Completion status
 *    - Substring matching (title)
 *    - Paging (page, page_size)
 *    - Sorting by created_at and completed_at
 *    - Privacy (ensuring only own todos appear)
 *    - Graceful handling of empty sets
 * 4. Ensures API respects pagination, ordering, and filtering accurately
 */
export async function test_api_todo_list_search_and_filtering(
  connection: api.IConnection,
) {
  // 1. Register new user
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12) + "Az1!";
  const joinHref = "https://test-host/login";
  const joinReferrer = "https://test-host/";
  const displayName = RandomGenerator.name();

  const userJoin = await api.functional.auth.user.join(connection, {
    body: {
      email,
      password: password as string & tags.Format<"password">,
      href: joinHref as string & tags.Format<"uri">,
      referrer: joinReferrer as string & tags.Format<"uri">,
      display_name: displayName,
    } satisfies ITodoListUser.ICreate,
  });
  typia.assert(userJoin);

  // 2. Login as the user
  const userLogin = await api.functional.auth.user.login(connection, {
    body: {
      email,
      password: password as string & tags.Format<"password">,
      href: joinHref as string & tags.Format<"uri">,
      referrer: joinReferrer as string & tags.Format<"uri">,
    } satisfies ITodoListUser.ILogin,
  });
  typia.assert(userLogin);

  // 3. Create list of Todos
  const todosToMake = 16;
  const titles: string[] = ArrayUtil.repeat(
    todosToMake,
    (i) =>
      RandomGenerator.paragraph({ sentences: 1, wordMin: 3, wordMax: 7 }) +
      (i % 3 === 0 ? " special" : ""),
  );
  const createdTodos: ITodoListTodo[] = [];
  for (let i = 0; i < todosToMake; ++i) {
    const todo = await api.functional.todoList.user.todos.create(connection, {
      body: {
        title: titles[i] as string & tags.MinLength<1> & tags.MaxLength<100>,
        description:
          i % 2 === 0 ? RandomGenerator.paragraph({ sentences: 2 }) : undefined,
      } satisfies ITodoListTodo.ICreate,
    });
    typia.assert(todo);
    createdTodos.push(todo);
  }

  // Mark some as completed (simulate via direct manipulation for later use in assertions)
  const completedIds = createdTodos
    .filter((_, i) => i % 2 === 0)
    .map((t) => t.id);
  // For simplicity, simulate completed flag (real endpoint to mark complete may not be available, so just set property for test assertions)
  const todosAugmented = createdTodos.map((t, i) => ({
    ...t,
    completed: i % 2 === 0,
    completed_at: i % 2 === 0 ? t.updated_at : null,
  }));

  // 4. SearchAPI: Filter for completed only
  let result = await api.functional.todoList.user.todos.index(connection, {
    body: { completed: true },
  });
  typia.assert(result);
  TestValidator.predicate(
    "completed filter returns all (and only) user's completed Todos",
    result.data.every((td) => td.completed === true),
  );
  TestValidator.equals(
    "completed filter returns correct count",
    result.data.length,
    todosAugmented.filter((t) => t.completed).length,
  );

  // Filter for incomplete only
  result = await api.functional.todoList.user.todos.index(connection, {
    body: { completed: false },
  });
  typia.assert(result);
  TestValidator.predicate(
    "incomplete filter returns only user's incomplete Todos",
    result.data.every((td) => td.completed === false),
  );
  TestValidator.equals(
    "incomplete filter returns correct count",
    result.data.length,
    todosAugmented.filter((t) => !t.completed).length,
  );

  // Filter by title substring
  const partial = RandomGenerator.substring(titles[4]);
  result = await api.functional.todoList.user.todos.index(connection, {
    body: { title: partial },
  });
  typia.assert(result);
  TestValidator.predicate(
    "title substring filter returns only matching Todos",
    result.data.every((td) => td.title.includes(partial)),
  );

  // 5. Pagination (pages, page_size)
  result = await api.functional.todoList.user.todos.index(connection, {
    body: { page: 2, page_size: 5 },
  });
  typia.assert(result);
  TestValidator.equals(
    "pagination meta (second page, limit 5)",
    result.pagination.current,
    2,
  );
  TestValidator.equals("pagination meta limit", result.pagination.limit, 5);
  TestValidator.predicate(
    "result count matches page size or less",
    result.data.length <= 5,
  );

  // 6. Order by created_at ascending
  result = await api.functional.todoList.user.todos.index(connection, {
    body: { order_by: "created_at", order_dir: "asc" },
  });
  typia.assert(result);
  TestValidator.predicate(
    "todos sorted by created_at ascending",
    result.data.every(
      (td, idx, arr) => idx === 0 || td.created_at >= arr[idx - 1].created_at,
    ),
  );

  // Order by created_at descending
  result = await api.functional.todoList.user.todos.index(connection, {
    body: { order_by: "created_at", order_dir: "desc" },
  });
  typia.assert(result);
  TestValidator.predicate(
    "todos sorted by created_at descending",
    result.data.every(
      (td, idx, arr) => idx === 0 || td.created_at <= arr[idx - 1].created_at,
    ),
  );

  // Order by completed_at ascending for completed todos
  result = await api.functional.todoList.user.todos.index(connection, {
    body: { order_by: "completed_at", order_dir: "asc", completed: true },
  });
  typia.assert(result);
  TestValidator.predicate(
    "completed todos sorted by completed_at ascending",
    result.data.every(
      (td, idx, arr) =>
        idx === 0 ||
        td.completed_at === null ||
        td.completed_at === undefined ||
        td.completed_at >= arr[idx - 1].completed_at!,
    ),
  );

  // 7. Per-user privacy: another user shouldn't see these Todos
  const newEmail = typia.random<string & tags.Format<"email">>();
  const newPassword = RandomGenerator.alphaNumeric(10) + "Az2!";
  const join2 = await api.functional.auth.user.join(connection, {
    body: {
      email: newEmail,
      password: newPassword as string & tags.Format<"password">,
      href: joinHref as string & tags.Format<"uri">,
      referrer: joinReferrer as string & tags.Format<"uri">,
    } satisfies ITodoListUser.ICreate,
  });
  typia.assert(join2);
  const login2 = await api.functional.auth.user.login(connection, {
    body: {
      email: newEmail,
      password: newPassword as string & tags.Format<"password">,
      href: joinHref as string & tags.Format<"uri">,
      referrer: joinReferrer as string & tags.Format<"uri">,
    } satisfies ITodoListUser.ILogin,
  });
  typia.assert(login2);
  // new user should have 0 todos
  const resultOtherUser = await api.functional.todoList.user.todos.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(resultOtherUser);
  TestValidator.equals(
    "other user sees zero todos (privacy)",
    resultOtherUser.data.length,
    0,
  );

  // 8. Empty page logic: excessive page index should yield empty result set
  result = await api.functional.todoList.user.todos.index(connection, {
    body: { page: 999 },
  });
  typia.assert(result);
  TestValidator.equals("empty page returns 0 data", result.data.length, 0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validates that an authenticated user can correctly retrieve detailed
 * information for a specific user by userId.
 *
 * 1. Register (join) as a new user to create an authenticated session for the
 *    test.
 * 2. Use the issued user id from registration to fetch the user details.
 * 3. Validate that all main user fields (id, email, display_name, created_at,
 *    updated_at) are present and values match those from registration.
 * 4. Ensure no authentication credential (such as password or token) or
 *    confidential fields are leaked in the user detail response.
 * 5. Assert that access control works: fetching details for a valid userId is
 *    permitted, but fetching a random/inexistent userId returns an error.
 */
export async function test_api_user_detail_retrieval_with_valid_authentication(
  connection: api.IConnection,
) {
  // 1. Register (join) as a new user
  const userCreateBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoListUser.ICreate;

  const joinOutput: ITodoListUser.IAuthorized =
    await api.functional.auth.user.join(connection, {
      body: userCreateBody,
    });
  typia.assert(joinOutput);

  // Use the user id for detail retrieval
  const userId = joinOutput.id;

  // 2. Retrieve user details for the created user id
  const userDetail: ITodoListUser = await api.functional.todoList.user.users.at(
    connection,
    {
      userId: userId,
    },
  );
  typia.assert(userDetail);

  // 3. Validate returned fields match registration
  TestValidator.equals("user id matches", userDetail.id, joinOutput.id);
  TestValidator.equals(
    "user email matches",
    userDetail.email,
    joinOutput.email,
  );
  TestValidator.equals(
    "user display_name matches",
    userDetail.display_name,
    joinOutput.display_name,
  );
  TestValidator.equals(
    "user created_at matches",
    userDetail.created_at,
    joinOutput.created_at,
  );
  TestValidator.equals(
    "user updated_at matches",
    userDetail.updated_at,
    joinOutput.updated_at,
  );

  // 4. Ensure sensitive information is not present
  TestValidator.predicate(
    "no confidential authentication fields leaked (password/token)",
    !Object.prototype.hasOwnProperty.call(userDetail, "password") &&
      !Object.prototype.hasOwnProperty.call(userDetail, "token"),
  );

  // 5. Fetch user details for a nonexistent userId should error
  await TestValidator.error(
    "retrieving details for a non-existent userId returns error",
    async () => {
      await api.functional.todoList.user.users.at(connection, {
        userId: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validate that a newly registered user can update their own email, password,
 * and display name via the profile update endpoint.
 *
 * This test performs the following steps:
 *
 * 1. Register a new user account (POST /auth/user/join) to establish initial
 *    authentication and collect the userId.
 * 2. Prepare and perform a successful update of all profile fields via PUT
 *    /todoList/user/users/{userId}:
 *
 *    - Change the email (to another unique, random valid email)
 *    - Change the password (to a new strong password string)
 *    - Change the display_name (set to a random friendly name)
 * 3. Verify in the response that:
 *
 *    - The email was updated and reflects the new unique value
 *    - The display_name shows the newly set value
 *    - The id and created_at fields are unchanged, but updated_at is refreshed
 * 4. Perform a second update that clears the display_name to null, using the same
 *    endpoint, and verify it is removed (null).
 * 5. Check that all business validations and type-format requirements (email,
 *    password min length) are satisfied by the test data.
 */
export async function test_api_user_profile_update_self_success(
  connection: api.IConnection,
) {
  // 1. Register a new user to obtain authentication and initial user profile
  const initialEmail = typia.random<string & tags.Format<"email">>();
  const initialPassword = RandomGenerator.alphaNumeric(12) + "A!";
  const initialDisplayName = RandomGenerator.name();
  const initialHref = "https://example.com/welcome";
  const initialReferrer = "https://google.com/";

  const userJoin = await api.functional.auth.user.join(connection, {
    body: {
      email: initialEmail,
      password: initialPassword satisfies string,
      href: initialHref,
      referrer: initialReferrer,
      display_name: initialDisplayName,
    } satisfies ITodoListUser.ICreate,
  });
  typia.assert(userJoin);
  // Use authorized fields for baseline
  const userId = userJoin.id;
  const createdAt = userJoin.created_at;
  const updatedAt1 = userJoin.updated_at;
  TestValidator.equals("email set on join", userJoin.email, initialEmail);
  TestValidator.equals(
    "display_name set on join",
    userJoin.display_name,
    initialDisplayName,
  );

  // 2. Update all modifiable fields: new email, new password, new display_name
  const updateEmail = typia.random<string & tags.Format<"email">>();
  const updatePassword = RandomGenerator.alphaNumeric(14) + "bB2_";
  const updateDisplayName = RandomGenerator.name();
  const updateResp = await api.functional.todoList.user.users.update(
    connection,
    {
      userId: userId,
      body: {
        email: updateEmail,
        password: updatePassword satisfies string,
        display_name: updateDisplayName,
      } satisfies ITodoListUser.IUpdate,
    },
  );
  typia.assert(updateResp);
  TestValidator.equals("userId unchanged after update", updateResp.id, userId);
  TestValidator.equals(
    "email updated successfully",
    updateResp.email,
    updateEmail,
  );
  TestValidator.equals(
    "display_name updated successfully",
    updateResp.display_name,
    updateDisplayName,
  );
  TestValidator.equals(
    "created_at unchanged after update",
    updateResp.created_at,
    createdAt,
  );
  TestValidator.notEquals(
    "updated_at refreshed after update",
    updateResp.updated_at,
    updatedAt1,
  );

  // 3. Confirm password cannot be checked directly but the change is accepted by server (no error)

  // 4. Now clear display_name to null and validate removal
  const updateResp2 = await api.functional.todoList.user.users.update(
    connection,
    {
      userId: userId,
      body: {
        display_name: null,
      } satisfies ITodoListUser.IUpdate,
    },
  );
  typia.assert(updateResp2);
  TestValidator.equals(
    "display_name cleared (nullified)",
    updateResp2.display_name,
    null,
  );
  TestValidator.equals(
    "userId unchanged after clearing display_name",
    updateResp2.id,
    userId,
  );
  TestValidator.equals(
    "email remains after display_name cleared",
    updateResp2.email,
    updateEmail,
  );
  TestValidator.notEquals(
    "updated_at changed after clearing display_name",
    updateResp2.updated_at,
    updateResp.updated_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Verifies that updating a user's profile to use an email address already
 * registered to another account fails.
 *
 * 1. Register User A (will attempt duplicate email assignment).
 * 2. Register User B (unique email that will be used for the duplicate attempt).
 * 3. Switch authentication back to User A.
 * 4. Attempt to update User A's email to User B's email.
 * 5. Confirm that update fails due to duplicate email, verifying backend
 *    uniqueness enforcement.
 */
