import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

export async function postAuthUserPasswordReset(props: {
  body: ITodoListUser.IResetPassword;
}): Promise<ITodoListUser.IPasswordResetStatus> {
  let decoded: unknown;
  try {
    decoded = jwt.verify(
      props.body.token,
      process.env.PASSWORD_RESET_SECRET || "",
    );
  } catch (_) {
    return { success: false, message: "Invalid or expired reset token." };
  }
  if (
    typeof decoded !== "object" ||
    !decoded ||
    (typeof (decoded as any).email !== "string" &&
      typeof (decoded as any).userId !== "string" &&
      typeof (decoded as any).sub !== "string")
  ) {
    return {
      success: false,
      message: "Invalid or incomplete reset token payload.",
    };
  }
  const maybeEmail =
    typeof (decoded as any).email === "string"
      ? (decoded as any).email
      : undefined;
  const maybeUserId =
    typeof (decoded as any).userId === "string"
      ? (decoded as any).userId
      : undefined;
  const maybeSub =
    typeof (decoded as any).sub === "string" ? (decoded as any).sub : undefined;
  const user = await MyGlobal.prisma.todo_list_users.findFirst({
    where: {
      ...(maybeEmail ? { email: maybeEmail } : {}),
      ...(maybeUserId ? { id: maybeUserId } : maybeSub ? { id: maybeSub } : {}),
    },
  });
  if (!user) {
    return { success: false, message: "No account found for token." };
  }
  const newPasswordHash = await PasswordUtil.hash(props.body.password);
  await MyGlobal.prisma.todo_list_users.update({
    where: { id: user.id },
    data: {
      password_hash: newPasswordHash,
      updated_at: toISOStringSafe(new Date()),
    },
  });
  await MyGlobal.prisma.todo_list_user_sessions.deleteMany({
    where: { todo_list_user_id: user.id },
  });
  return {
    success: true,
    message:
      "Password has been reset. Please log in with your new credentials.",
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserSession";
import { IPageITodoListUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListUserSession";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

export async function patchTodoListUsersUserIdSessions(props: {
  userId: string & tags.Format<"uuid">;
  body: ITodoListUserSession.IRequest;
}): Promise<IPageITodoListUserSession.ISummary> {
  const {
    ip,
    href,
    referrer,
    created_from,
    created_to,
    expired,
    page,
    limit,
    sort,
  } = props.body;

  const sortMap = {
    "created_at:desc": [{ created_at: "desc" }],
    "created_at:asc": [{ created_at: "asc" }],
    "expired_at:desc": [{ expired_at: "desc" }, { created_at: "desc" }],
    "expired_at:asc": [{ expired_at: "asc" }, { created_at: "desc" }],
  } as const;
  const orderBy = [...sortMap[sort ?? "created_at:desc"]];

  // Build Prisma where condition
  const whereCond = {
    todo_list_user_id: props.userId,
    ...(typeof ip === "string" && ip !== "" && { ip: { contains: ip } }),
    ...(typeof href === "string" &&
      href !== "" && { href: { contains: href } }),
    ...(typeof referrer === "string" &&
      referrer !== "" && { referrer: { contains: referrer } }),
    ...(created_from && { created_at: { gte: created_from } }),
    ...(created_to && {
      created_at: {
        ...(created_from && { gte: created_from }),
        lte: created_to,
      },
    }),
    ...(expired === true && { expired_at: { not: null } }),
  };

  const pageNum = (page > 0 ? page : 1) satisfies number as number;
  const pageSize = (limit > 0 && limit <= 100
    ? limit
    : 20) satisfies number as number;
  const skip = (pageNum - 1) * pageSize;

  // Fetch sessions
  const [sessions, total] = await Promise.all([
    MyGlobal.prisma.todo_list_user_sessions.findMany({
      where: whereCond,
      orderBy: orderBy,
      skip,
      take: pageSize,
    }),
    MyGlobal.prisma.todo_list_user_sessions.count({ where: whereCond }),
  ]);

  // Fetch user info for each session (since include: {user:true} was broken)
  const usersMap = new Map<string, ITodoListUser.ISummary>();
  for (const session of sessions) {
    if (!usersMap.has(session.todo_list_user_id)) {
      const user = await MyGlobal.prisma.todo_list_users.findUnique({
        where: { id: session.todo_list_user_id },
        select: {
          id: true,
          email: true,
          display_name: true,
          created_at: true,
        },
      });
      if (user) {
        usersMap.set(user.id, {
          id: user.id,
          email: user.email,
          display_name: user.display_name ?? undefined,
          created_at: toISOStringSafe(user.created_at),
        });
      }
    }
  }

  const data = sessions.map((s) => ({
    id: s.id,
    ip: s.ip,
    href: s.href,
    referrer: s.referrer,
    created_at: toISOStringSafe(s.created_at),
    expired_at: s.expired_at ? toISOStringSafe(s.expired_at) : undefined,
    user: usersMap.get(s.todo_list_user_id)!,
  }));

  return {
    pagination: {
      current: pageNum satisfies number as number,
      limit: pageSize satisfies number as number,
      records: total satisfies number as number,
      pages: Math.ceil(total / pageSize) satisfies number as number,
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserJoin(props: {
  body: ITodoListUser.ICreate;
}): Promise<ITodoListUser.IAuthorized> {
  // Check for duplicate email
  const existingUser = await MyGlobal.prisma.todo_list_users.findFirst({
    where: { email: props.body.email },
  });
  if (existingUser) {
    throw new HttpException("Email already registered", 409);
  }

  // Password hash
  const hashedPassword = await PasswordUtil.hash(props.body.password);

  // Timestamps as ISO 8601 string & tags.Format<'date-time'>
  const now = toISOStringSafe(new Date());

  // Create user
  const user = await MyGlobal.prisma.todo_list_users.create({
    data: {
      id: v4(),
      email: props.body.email,
      password_hash: hashedPassword,
      display_name: props.body.display_name ?? null,
      created_at: now,
      updated_at: now,
    },
  });

  // Calculate expiries (access: 1h, refresh: 7d) as string
  const accessExpires = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refreshExpires = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );

  // Create session with required 'ip' field; use empty string if no ip is available
  const session = await MyGlobal.prisma.todo_list_user_sessions.create({
    data: {
      id: v4(),
      todo_list_user_id: user.id,
      ip: "", // No ip available, set to empty string for required field
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: now,
      expired_at: accessExpires,
    },
  });

  // JWT token creation
  const accessToken = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: session.id,
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );
  const refreshToken = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  // Trigger verification email (fake placeholder; real system will call actual logic)
  // await VerificationService.sendVerificationEmail(user.email, user.id);

  return {
    id: user.id,
    email: user.email,
    display_name:
      typeof user.display_name === "string"
        ? user.display_name
        : user.display_name === null
          ? null
          : undefined,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: accessExpires,
      refreshable_until: refreshExpires,
    },
    user: {
      id: user.id,
      email: user.email,
      display_name:
        typeof user.display_name === "string"
          ? user.display_name
          : user.display_name === null
            ? null
            : undefined,
      created_at: toISOStringSafe(user.created_at),
      updated_at: toISOStringSafe(user.updated_at),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserRefresh(props: {
  body: ITodoListUser.IRefresh;
}): Promise<ITodoListUser.IAuthorized> {
  // 1. Decode and verify refresh token
  let decoded: { id: string; session_id: string; type: "user" };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as { id: string; session_id: string; type: "user" };
  } catch (err) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }
  // 2. Verify JWT type
  if (decoded.type !== "user") {
    throw new HttpException("Invalid token type for user flow.", 403);
  }
  // 3. Load matching session with user from DB
  const session = await MyGlobal.prisma.todo_list_user_sessions.findFirst({
    where: {
      id: decoded.session_id,
      todo_list_user_id: decoded.id,
    },
    include: {
      user: true,
    },
  });
  if (!session) {
    throw new HttpException("Session not found.", 401);
  }
  if (
    session.expired_at &&
    new Date(session.expired_at).getTime() <= Date.now()
  ) {
    throw new HttpException("Session expired; login required.", 401);
  }
  if (!session.user) {
    throw new HttpException("User for session not found.", 401);
  }
  // 4. Issue new tokens with same session_id & user id
  const now = new Date();
  const accessExpiresAt = toISOStringSafe(
    new Date(now.getTime() + 60 * 60 * 1000),
  );
  const refreshExpiresAt = toISOStringSafe(
    new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000),
  );
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "user",
        id: session.todo_list_user_id,
        session_id: session.id,
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "user",
        id: session.todo_list_user_id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpiresAt,
    refreshable_until: refreshExpiresAt,
  };
  // 5. Update session expiration
  await MyGlobal.prisma.todo_list_user_sessions.update({
    where: { id: session.id },
    data: { expired_at: refreshExpiresAt },
  });
  // 6. Return authorized response
  return {
    id: session.user.id,
    email: session.user.email,
    display_name: session.user.display_name ?? null,
    created_at: toISOStringSafe(session.user.created_at),
    updated_at: toISOStringSafe(session.user.updated_at),
    token,
    user: {
      id: session.user.id,
      email: session.user.email,
      display_name: session.user.display_name ?? null,
      created_at: toISOStringSafe(session.user.created_at),
      updated_at: toISOStringSafe(session.user.updated_at),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserLogin(props: {
  body: ITodoListUser.ILogin;
}): Promise<ITodoListUser.IAuthorized> {
  // 1. Find user by email
  const user = await MyGlobal.prisma.todo_list_users.findFirst({
    where: { email: props.body.email },
  });
  if (!user) {
    throw new HttpException("Invalid credentials", 401);
  }

  // 2. Password verification
  const valid = await PasswordUtil.verify(
    props.body.password,
    user.password_hash,
  );
  if (!valid) {
    throw new HttpException("Invalid credentials", 401);
  }

  // 3. Prepare session and expiration times
  const now = toISOStringSafe(new Date());
  const accessExpire = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refreshExpire = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );

  // 4. Always include ip (empty string if not present), to satisfy Prisma schema
  const session = await MyGlobal.prisma.todo_list_user_sessions.create({
    data: {
      id: v4(),
      todo_list_user_id: user.id,
      ip: (props.body.ip ?? "") satisfies string as string,
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: now,
      expired_at: accessExpire,
    },
  });

  // 5. Create JWT tokens
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "user",
        id: user.id,
        session_id: session.id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "user",
        id: user.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpire,
    refreshable_until: refreshExpire,
  };

  // 6. Return authorized DTO (with proper null/undefined handling for display_name)
  return {
    id: user.id,
    email: user.email,
    display_name:
      user.display_name === null ? null : (user.display_name ?? undefined),
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    token,
    user: {
      id: user.id,
      email: user.email,
      display_name:
        user.display_name === null ? null : (user.display_name ?? undefined),
      created_at: toISOStringSafe(user.created_at),
      updated_at: toISOStringSafe(user.updated_at),
    },
  };
}

